__attribute__((import_module("env"),import_name("sin"))) double js_sin(double);
__attribute__((import_module("env"),import_name("cos"))) double js_cos(double);
static double min(double a,double b){return a<b?a:b;}static double max(double a,double b){return a>b?a:b;}
static void map(double*h,double*p,double W,double H,int kind,double x,double y,double*out){if(kind){double u=2*x/W-1,v=2*y/H-1;if(kind==2){int axis=(int)p[3];double t=axis?v:u,angle=max(.001,min(1.55,p[0])),z=js_cos(angle*t)-js_cos(angle),den=max(.3,1+p[2]*z),a=(js_sin(angle*t)/js_sin(angle)+p[1]*z)/den,b=((axis?u:v)+p[4]*z)/den;if(axis){x=W/2*(1+b);y=H/2*(1+a);}else{x=W/2*(1+a);y=H/2*(1+b);}x+=(1-u*u)*p[5]+(1-v*v)*p[6]+u*(1-u*u)*p[7]+u*(1-v*v)*p[8];y+=(1-u*u)*p[9]+(1-v*v)*p[10]+v*(1-u*u)*p[11]+v*(1-v*v)*p[12];}else{x+=(1-u*u)*(p[0]+p[1]*v)+p[2]*(1-v*v)+p[6]*u*(1-u*u)+p[8]*u*(1-v*v);y+=(1-v*v)*(p[3]+p[4]*u)+p[5]*(1-u*u)+p[7]*v*(1-u*u)+p[9]*v*(1-v*v);}}double d=h[6]*x+h[7]*y+1;out[0]=(h[0]*x+h[1]*y+h[2])/d;out[1]=(h[3]*x+h[4]*y+h[5])/d;}
static double at(float*maps,int w,int h,double scale,int sym,double x,double y){x=x*scale;y=y*scale;if(x<0||y<0||x>=w-1||y>=h-1)return 12;int ix=(int)x,iy=(int)y,i=iy*w+ix;double u=x-ix,v=y-iy;float*m=maps+sym*w*h;return(m[i]*(1-u)+m[i+1]*u)*(1-v)+(m[i+w]*(1-u)+m[i+w+1]*u)*v;}
__attribute__((export_name("score"))) double score(double*hom,double*p,double W,double H,int kind,float*maps,int w,int h,double scale,double*pts,int n,double*heads,int hn,int rank,double fraction,double*errors){double q[2],sum=0;for(int i=0;i<n;i++){double*c=pts+i*3;map(hom,p,W,H,kind,c[0],c[1],q);double d=at(maps,w,h,scale,(int)c[2],q[0],q[1]);errors[i]=min(rank?25:64,d*d);if(rank)sum+=errors[i];}if(rank)return sum/n;for(int gap=n/2;gap>0;gap/=2)for(int i=gap;i<n;i++){double v=errors[i];int j=i;while(j>=gap&&errors[j-gap]>v){errors[j]=errors[j-gap];j-=gap;}errors[j]=v;}int count=(int)(n*fraction);for(int i=0;i<count;i++)sum+=errors[i];double base=sum/count,head=0;int offset=0;for(int bit=0;bit<24;bit++){double zero=0,one=0;for(int j=0;j<hn/24;j++){double*c=heads+offset;offset+=2;map(hom,p,W,H,kind,c[0],c[1],q);double a=at(maps,w,h,scale,8,q[0],q[1]),b=at(maps,w,h,scale,0,q[0],q[1]);zero+=min(36,a*a);one+=min(36,b*b);}head+=min(zero,one);}return base+head/72*.35;}
__attribute__((import_module("env"),import_name("checkn"))) void checkn(int);
__attribute__((export_name("rank_grid"))) void rank_grid(double*hom,double*p,double W,double H,float*maps,int w,int h,double scale,double*pts,int n,double bestCost,double bestScore,double*out){double bestP[10]={0};double errors[256];for(int shift=-6;shift<=6;shift+=6)for(int vertical=-6;vertical<=6;vertical+=6)for(int compress=0;compress<=6;compress+=6)for(int vc=0;vc<=3;vc+=3){for(int k=0;k<13;k++)p[k]=0;p[0]=shift;p[5]=vertical;p[6]=compress;p[7]=vc;checkn(n);double cost=score(hom,p,W,H,1,maps,w,h,scale,pts,n,0,0,1,1,errors),value=1/(1+cost);if(value>bestScore||(value==bestScore&&cost<bestCost)){bestCost=cost;bestScore=value;for(int k=0;k<10;k++)bestP[k]=p[k];}}for(int shift=-6;shift<=6;shift+=6)for(int vertical=-6;vertical<=6;vertical+=6)for(int compress=0;compress>=-3;compress-=3){for(int k=0;k<13;k++)p[k]=0;p[2]=shift;p[3]=vertical;p[8]=compress;p[9]=compress;checkn(n);double cost=score(hom,p,W,H,1,maps,w,h,scale,pts,n,0,0,1,1,errors),value=1/(1+cost);if(value>bestScore){bestCost=cost;bestScore=value;for(int k=0;k<10;k++)bestP[k]=p[k];}}out[0]=bestCost;out[1]=bestScore;for(int k=0;k<10;k++)out[2+k]=bestP[k];}
